    res.send('Post updated');
  } else {
    res.status(400).send('Invalid input');
  }
});

router.delete('/posts/:id', (req: Request, res: Response): void => {
  const postId = Number(req.params.id);
  deletePost(postId);
  res.send('Post deleted');
});

