import { Router, type Request, type Response } from "express";
import { TimeEntry, getTimeEntriesByUserId, getTimeEntryById, insertTimeEntry } from "../db/time-entries-table";

export const router = Router();

router.get("/time-entries", (req: Request, res: Response): void => {
  const userId = Number(req.query.userId);
  if (isNaN(userId)) {
    res.status(400).send("Invalid user ID");
    return;
  }
  const timeEntries = getTimeEntriesByUserId(userId);
  res.json(timeEntries);
});

router.get("/time-entries/:id", (req: Request, res: Response): void => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    res.status(400).send("Invalid entry ID");
    return;
  }
  const timeEntry = getTimeEntryById(id);
  if (timeEntry) {
    res.json(timeEntry);
  } else {
    res.status(404).send("Time entry not found");
  }
});

router.post("/time-entries", (req: Request, res: Response): void => {
  const entry: Omit<TimeEntry, "id"> = req.body;
  if (!entry.user_id || !entry.project_id || !entry.start_time || !entry.end_time || !entry.description || !entry.billing_rate || !entry.budget) {
    res.status(400).send("Missing required fields");
    return;
  }
  insertTimeEntry(entry);
  res.status(201).send("Time entry created");
});

