    res.status(200).send(`Joined room ${roomCode}. New player count: ${room.playerCount + 1}`);
  } else {
    res.status(404).send(`Room with code ${roomCode} not found.`);
  }
});

router.post("/rooms/:roomCode/leave", (req: Request, res: Response) => {
  const roomCode = req.params.roomCode;
  const room = getRoom(roomCode);
