import { Router, type Request, type Response } from "express";
import { getPlotById, updatePlotStatus } from "../db/plots-table";
import { insertReservation, getReservationsByPlot } from "../db/reservations-table";

export const router = Router();

router.post("/reserve", (req: Request, res: Response) => {
  const { memberId, plotId }: { memberId: number, plotId: number } = req.body;
  const plot = getPlotById(plotId);

  if (!plot || plot.status !== "available") {
    res.status(400).send("Plot is not available for reservation.");
    return;
  }

  insertReservation(memberId, plotId, Date.now());
  updatePlotStatus(plotId, "reserved", `${memberId}`);
  res.status(201).send("Plot reserved successfully.");
});

router.post("/reassign", (req: Request, res: Response) => {
  const { plotId, newMemberId }: { plotId: number, newMemberId: number } = req.body;
  const plot = getPlotById(plotId);

  if (!plot || plot.status !== "reserved") {
    res.status(400).send("Plot is not currently reserved.");
    return;
  }

  const reservations = getReservationsByPlot(plotId);
  const latestReservation = reservations.sort((a, b) => b.reservationTimestamp - a.reservationTimestamp)[0];

  if (latestReservation && latestReservation.memberId === newMemberId) {
    res.status(400).send("Plot is already reserved by the specified member.");
    return;
  }

  insertReservation(newMemberId, plotId, Date.now());
  updatePlotStatus(plotId, "reserved", `${newMemberId}`);
  res.status(200).send("Plot reassigned successfully.");
});

