import { Router, type Request, type Response } from "express";
import { Workout, getWorkoutsByClientId, getWorkoutById, insertWorkout } from "../db/workouts-table";
import { ClientTrainerRow, getTrainerClients } from "../db/client-trainer-table";

export const router = Router();

router.get("/workouts", (req: Request, res: Response) => {
  const trainerId = Number(req.query.trainerId);
  if (isNaN(trainerId)) {
    res.status(400).send("Invalid trainerId");
    return;
  }

  const clientTrainerRows: ClientTrainerRow[] = getTrainerClients(trainerId);
  const clientIds = clientTrainerRows.map((row: ClientTrainerRow) => row.clientId);

  const workouts: Workout[] = [];
  clientIds.forEach((clientId: number) => {
    workouts.push(...getWorkoutsByClientId(clientId));
  });

  res.json(workouts);
});

router.get("/workouts/:id", (req: Request, res: Response) => {
  const workoutId = Number(req.params.id);
  if (isNaN(workoutId)) {
    res.status(400).send("Invalid workout ID");
    return;
  }

  const workout = getWorkoutById(workoutId);
  if (!workout) {
    res.status(404).send("Workout not found");
