import { Router, type Request, type Response } from "express";
import { Reservation, db, getReservationsByDriverId, getReservationsBySpotNumber, insertReservation } from "../db/reservations-table";

export const router = Router();

router.post("/check-availability", (req: Request, res: Response) => {
  const { spotNumber } = req.body;
  const reservations = getReservationsBySpotNumber(Number(spotNumber));
  if (reservations.length === 0) {
    res.status(200).json({ available: true });
  } else {
    res.status(200).json({ available: false });
  }
});

router.post("/reserve", (req: Request, res: Response) => {
  const { driverId, spotNumber, reservedTime } = req.body;
  const reservations = getReservationsBySpotNumber(Number(spotNumber));
  if (reservations.length === 0) {
    insertReservation(Number(driverId), Number(spotNumber), reservedTime);
    res.status(201).json({ message: "Reservation successful" });
  } else {
    res.status(409).json({ message: "Spot already reserved" });
  }
});

router.post("/force-open", (req: Request, res: Response) => {
  const { spotNumber } = req.body;
  db.prepare(`DELETE FROM reservations WHERE spotNumber = ?`).run(Number(spotNumber));
  res.status(200).json({ message: "Spot forced open" });
});

