import { addItem, getAllItems, getItemById, updateItemQuantity, deleteItem, type InventoryItem } from "../db/inventory-items-table";
import { insertWithdrawal, getWithdrawals, approveWithdrawal, type Withdrawal } from "../db/withdrawals-table";

export const router = Router();

router.post("/items", (req: Request, res: Response): void => {
  const { name, quantity, donorVolunteerId } = req.body;
  addItem(name, quantity, donorVolunteerId);
  res.status(201).send();
});

router.get("/items", (req: Request, res: Response): void => {
  const items: InventoryItem[] = getAllItems();
  res.json(items);
});

router.get("/items/:id", (req: Request, res: Response): void => {
  const id: number = Number(req.params.id);
  const item: InventoryItem | undefined = getItemById(id);
  if (item) {
    res.json(item);
  } else {
    res.status(404).send();
  }
});

router.put("/items/:id", (req: Request, res: Response): void => {
  const id: number = Number(req.params.id);
  const { quantity } = req.body;
  updateItemQuantity(id, quantity);
  res.send();
});

router.delete("/items/:id", (req: Request, res: Response): void => {
  const id: number = Number(req.params.id);
  deleteItem(id);
  res.send();
});

router.post("/withdrawals", (req: Request, res: Response): void => {
  const { amount } = req.body;
  insertWithdrawal(amount);
  res.status(201).send();
});

router.get("/withdrawals", (req: Request, res: Response): void => {
  const withdrawals: Withdrawal[] = getWithdrawals();
  res.json(withdrawals);
});

router.put("/withdrawals/:id/approve", (req: Request, res: Response): void => {
  const id: number = Number(req.params.id);
  approveWithdrawal(id);
  res.send();
});

import type { Request, Response, NextFunction } from "express";
import { router } from "../routes/inventory-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to the withdrawal endpoint
  if (req.method !== "POST" || req.path !== "/inventory/withdraw") {
    return next();
  }

  const withdrawalAmount = Number(req.body.amount);
  const isApprovedBySiteLead = req.body.approvedBySiteLead;

  // Check if the withdrawal amount is large and not approved by the site lead
  if (withdrawalAmount > 100 && !isApprovedBySiteLead) {
    res.status(403).send("Large withdrawals require site lead approval.");
    return;
  }

  next();
}

import { Router, type Request, type Response } from "express";
import { Order, insertOrder, getOrders, getOrderById } from "../db/orders-table";

export const router = Router();

