import { Router, type Request, type Response } from "express";
import { getSubmissionById, updateSubmissionReviewStatus } from "../db/submissions-table";
import { getRoleByUserId } from "../db/roles-table";

export const router = Router();

router.post("/advance-submission/:id", (req: Request, res: Response) => {
  const submissionId = Number(req.params.id);
  const userId = Number(req.body.userId);

  const submission = getSubmissionById(submissionId);
  const userRole = getRoleByUserId(userId);

  if (!submission || !userRole || !(userRole.role === "editor" || userRole.role === "admin")) {
    res.status(403).send("Forbidden");
    return;
  }

  updateSubmissionReviewStatus(submissionId, "review");
  res.status(200).send("Submission advanced to review");
});

